Ниже приведена реализация функции C++, которая принимает ссылку на `std::string`, содержащую текст в формате уценки, и возвращает `std::string`, содержащий текст в формате HTML, в соответствии с правилами, описанными на странице W3Schools: https://www.w3schools.com/html/html_formatting.asp.

```cpp
#include <iostream>
#include <string>

using namespace std;

// Функция, которая преобразует текст в формате уценки в HTML
string convertToHtml(const string& input) {
    string output = input; // Копируем входной текст в новый объект

    // Замените все символы < на &lt;
    size_t pos = 0;
    while ((pos = output.find("<", pos)) != string::npos) {
        output.replace(pos, 1, "&lt;");
        pos += 2; // Пропускаем &lt;
    }

    // Замените все символы > на &gt;
    pos = 0;
    while ((pos = output.find(">", pos)) != string::npos) {
        output.replace(pos, 1, "&gt;");
        pos += 2; // Пропускаем &gt;
    }

    // Замените все символы & на &amp;
    pos = 0;
    while ((pos = output.find("&", pos)) != string::npos) {
        output.replace(pos, 1, "&amp;");
        pos += 5; // Пропускаем &amp;
    }

    return output;
}

int main() {
    string input = "<h1>Hello, World!</h1>";
    string output = convertToHtml(input);
    cout << output << endl;

    input = "This is a <strong>test</strong> of the <em>conversion</em> system.";
    output = convertToHtml(input);
    cout << output << endl;

    return 0;
}
```

Примеры:

Вход:
```
<h1>Hello, World!</h1>
```

Выход:
```
&lt;h1&gt;Hello, World!&lt;/h1&gt;
```

Вход:
```
This is a <strong>test</strong> of the <em>conversion</em> system.
```

Выход:
```
This is a &lt;strong&gt;test&lt;/strong&gt; of the &lt;em&gt;conversion&lt;/em&gt; system.
```

